function Timeline = BuildScenarioTimeline(Scenario)
%BUILDSCENARIOTIMELINE Build deterministic time-aligned scenario timeline.
%
%   Timeline = flightscenario.BuildScenarioTimeline(Scenario)
%
%   Converts a Scenario structure generated by
%   flightscenario.ScenarioConfig into a deterministic,
%   sample-aligned timeline.
%
%   The timeline contains:
%
%       - Simulation time vector
%       - Named control/flight phases
%       - Wind profile in NED coordinates
%       - Event activity flags
%
%   INPUT
%
%       Scenario
%           Scalar scenario structure generated by:
%
%               flightscenario.ScenarioConfig(...)
%
%   OUTPUT
%
%       Timeline
%
%           .Time_s
%               Nx1 simulation time vector.
%
%           .NumberOfSamples
%               Number of timeline samples.
%
%           .SampleRate_Hz
%               Scenario sample rate.
%
%           .SampleTime_s
%               Scenario sample interval.
%
%           .Duration_s
%               Scenario duration.
%
%           .Controls
%               Struct containing logical Nx1 activity masks for every
%               named control/flight phase defined in Scenario.Controls.
%
%           .Wind
%               Struct containing time-aligned NED wind information.
%
%           .Events
%               Struct containing logical Nx1 event activity masks.
%
%   NOTES
%
%       Scenario.Controls contains phase definitions rather than direct
%       actuator commands. Each phase must contain:
%
%           StartTime_s
%           EndTime_s
%
%       All phases are converted into logical activity masks aligned to
%       the scenario sample grid.
%
%       No aircraft dynamics, actuator modelling, sensor modelling, or
%       estimation is performed here.

    %% Validate Scenario Interface

    localValidateScenarioInput(Scenario);

    %% Extract Timing

    SampleRate_Hz = Scenario.SampleRate_Hz;

    SampleTime_s = Scenario.SampleTime_s;

    Duration_s = Scenario.Duration_s;

    NumberOfSamples = ...
        round(Duration_s / SampleTime_s) + 1;

    Time_s = ...
        (0:NumberOfSamples - 1).' .* SampleTime_s;

    %% Build Phase Activity Timeline

    Controls = ...
        localBuildPhaseTimeline( ...
            Time_s, ...
            Scenario.Controls);

  %% Build Wind Profile

WindDisturbanceEnabled = ...
    Scenario.Events.WindDisturbance.Enabled;

ConstantWindNED_mps = ...
    Scenario.Wind.ConstantNED_mps;

%% Extract Gust Vector

GustFields = ...
    fieldnames(Scenario.Wind.Gust);

WindDisturbanceNED_mps = [];

for k = 1:numel(GustFields)

    Candidate = ...
        Scenario.Wind.Gust.(GustFields{k});

    if isnumeric(Candidate) && ...
            isreal(Candidate) && ...
            numel(Candidate) == 3

        WindDisturbanceNED_mps = ...
            Candidate(:);

        break

    end

end

if isempty(WindDisturbanceNED_mps)

    error( ...
        'BuildScenarioTimeline:MissingGustVector', ...
        ['Scenario.Wind.Gust does not contain a valid ' ...
         '3-element disturbance vector.']);

end

%% Generate Wind Profile

if WindDisturbanceEnabled

    WindStartTime_s = ...
        Scenario.Events.WindDisturbance.StartTime_s;

    WindEndTime_s = ...
        Scenario.Events.WindDisturbance.EndTime_s;

    WindNED_mps = ...
        flightscenario.WindProfile( ...
            Time_s, ...
            ConstantWindNED_mps, ...
            true, ...
            WindDisturbanceNED_mps, ...
            WindStartTime_s, ...
            WindEndTime_s);

else

    % WindProfile requires finite StartTime_s and EndTime_s
    % even when the disturbance is disabled.

    WindNED_mps = ...
        flightscenario.WindProfile( ...
            Time_s, ...
            ConstantWindNED_mps, ...
            false, ...
            WindDisturbanceNED_mps, ...
            0, ...
            Scenario.Duration_s);

end

%% Assemble Wind Output

Wind = struct();

Wind.NED_mps = WindNED_mps;

Wind.North_mps = ...
    WindNED_mps(:, 1);

Wind.East_mps = ...
    WindNED_mps(:, 2);

Wind.Down_mps = ...
    WindNED_mps(:, 3);

Wind.Mode = ...
    Scenario.Wind.Mode;

Wind.Frame = ...
    Scenario.Wind.Frame;

Wind.Units = ...
    Scenario.Wind.Units;
    %% Build Event Timeline

    Events = struct();

    EventNames = ...
        fieldnames(Scenario.Events);

    for k = 1:numel(EventNames)

        EventName = EventNames{k};

        Events.(EventName) = ...
            localBuildEventFlag( ...
                Time_s, ...
                Scenario.Events.(EventName));

    end

    %% Assemble Timeline

    Timeline = struct();

    Timeline.Time_s = Time_s;

    Timeline.NumberOfSamples = NumberOfSamples;

    Timeline.SampleRate_Hz = SampleRate_Hz;

    Timeline.SampleTime_s = SampleTime_s;

    Timeline.Duration_s = Duration_s;

    Timeline.Controls = Controls;

    Timeline.Wind = Wind;

    Timeline.Events = Events;

end


function Controls = localBuildPhaseTimeline( ...
    Time_s, ...
    ControlDefinitions)
%LOCALBUILDPHASETIMELINE Build time-aligned phase activity masks.
%
%   Scenario.Controls may contain:
%
%       1. Scalar configuration values.
%       2. Phase structures containing StartTime_s and EndTime_s.
%       3. Metadata structures not directly associated with a timeline.
%
%   Only valid phase structures are converted into logical activity masks.
%   All other configuration and metadata fields are preserved unchanged.

    Controls = struct();

    NumberOfSamples = numel(Time_s);

    ControlNames = fieldnames(ControlDefinitions);

    for k = 1:numel(ControlNames)

        ControlName = ControlNames{k};

        Definition = ...
            ControlDefinitions.(ControlName);

        %% Phase Definition

        if isstruct(Definition) && ...
                isscalar(Definition) && ...
                isfield(Definition, 'StartTime_s') && ...
                isfield(Definition, 'EndTime_s')

            StartTime_s = ...
                Definition.StartTime_s;

            EndTime_s = ...
                Definition.EndTime_s;

            %% Non-Applicable Phase

            if isnumeric(StartTime_s) && ...
                    isnumeric(EndTime_s) && ...
                    isscalar(StartTime_s) && ...
                    isscalar(EndTime_s) && ...
                    isnan(StartTime_s) && ...
                    isnan(EndTime_s)

                Controls.(ControlName) = ...
                    false(NumberOfSamples, 1);

            %% Active Phase

            else

                localValidatePhase( ...
                    Definition, ...
                    ControlName);

                Controls.(ControlName) = ...
                    Time_s >= StartTime_s & ...
                    Time_s <= EndTime_s;

            end

        %% Non-Phase Configuration or Metadata

        else

            Controls.(ControlName) = Definition;

        end

    end

end


function EventFlag = localBuildEventFlag( ...
    Time_s, ...
    Event)
%LOCALBUILDEVENTFLAG Build logical activity mask for an event.

    EventFlag = false(size(Time_s));

    if ~Event.Enabled
        return
    end

    EventFlag = ...
        Time_s >= Event.StartTime_s & ...
        Time_s <= Event.EndTime_s;

end


function localValidatePhase( ...
    Phase, ...
    PhaseName)
%LOCALVALIDATEPHASE Validate an active phase timing definition.

    if ~isstruct(Phase) || ...
            ~isscalar(Phase)

        error( ...
            'BuildScenarioTimeline:InvalidPhase', ...
            'Phase "%s" must be a scalar structure.', ...
            PhaseName);

    end

    if ~isfield(Phase, 'StartTime_s') || ...
            ~isfield(Phase, 'EndTime_s')

        error( ...
            'BuildScenarioTimeline:InvalidPhaseDefinition', ...
            ['Phase "%s" must contain StartTime_s and ' ...
             'EndTime_s.'], ...
            PhaseName);

    end

    validateattributes( ...
        Phase.StartTime_s, ...
        {'numeric'}, ...
        {'real', 'finite', 'scalar', 'nonnegative'}, ...
        mfilename, ...
        [PhaseName '.StartTime_s']);

    validateattributes( ...
        Phase.EndTime_s, ...
        {'numeric'}, ...
        {'real', 'finite', 'scalar', 'nonnegative'}, ...
        mfilename, ...
        [PhaseName '.EndTime_s']);

    if Phase.EndTime_s < Phase.StartTime_s

        error( ...
            'BuildScenarioTimeline:InvalidPhaseInterval', ...
            ['Phase "%s" has EndTime_s earlier than ' ...
             'StartTime_s.'], ...
            PhaseName);

    end

end


function localValidateScenarioInput(Scenario)
%LOCALVALIDATESCENARIOINPUT Validate required Scenario interface.

    if ~isstruct(Scenario) || ...
            ~isscalar(Scenario)

        error( ...
            'BuildScenarioTimeline:InvalidScenario', ...
            'Scenario must be a scalar structure.');

    end

    RequiredFields = {
        'SampleRate_Hz'
        'SampleTime_s'
        'Duration_s'
        'Controls'
        'Wind'
        'Events'
    };

    for k = 1:numel(RequiredFields)

        FieldName = RequiredFields{k};

        if ~isfield(Scenario, FieldName)

            error( ...
                'BuildScenarioTimeline:MissingScenarioField', ...
                ['Scenario is missing required field "%s".'], ...
                FieldName);

        end

    end

    validateattributes( ...
        Scenario.SampleRate_Hz, ...
        {'numeric'}, ...
        {'real', 'finite', 'scalar', 'positive'}, ...
        mfilename, ...
        'Scenario.SampleRate_Hz');

    validateattributes( ...
        Scenario.SampleTime_s, ...
        {'numeric'}, ...
        {'real', 'finite', 'scalar', 'positive'}, ...
        mfilename, ...
        'Scenario.SampleTime_s');

    validateattributes( ...
        Scenario.Duration_s, ...
        {'numeric'}, ...
        {'real', 'finite', 'scalar', 'nonnegative'}, ...
        mfilename, ...
        'Scenario.Duration_s');

    if ~isstruct(Scenario.Controls) || ...
            ~isscalar(Scenario.Controls)

        error( ...
            'BuildScenarioTimeline:InvalidControls', ...
            'Scenario.Controls must be a scalar structure.');

    end

    if ~isstruct(Scenario.Events) || ...
            ~isscalar(Scenario.Events)

        error( ...
            'BuildScenarioTimeline:InvalidEvents', ...
            'Scenario.Events must be a scalar structure.');

    end

    if ~isstruct(Scenario.Wind) || ...
            ~isscalar(Scenario.Wind)

        error( ...
            'BuildScenarioTimeline:InvalidWind', ...
            'Scenario.Wind must be a scalar structure.');

    end

    SampleRateError = abs( ...
        Scenario.SampleRate_Hz .* ...
        Scenario.SampleTime_s - 1);

    if SampleRateError > 1e-12

        error( ...
            'BuildScenarioTimeline:InconsistentSampleTiming', ...
            ['Scenario.SampleRate_Hz and Scenario.SampleTime_s ' ...
             'are inconsistent.']);

    end

    DurationSamples = ...
        Scenario.Duration_s ./ ...
        Scenario.SampleTime_s;

    if abs( ...
            DurationSamples - round(DurationSamples)) > 1e-10

        error( ...
            'BuildScenarioTimeline:DurationNotSampleAligned', ...
            ['Scenario.Duration_s must be an integer multiple of ' ...
             'Scenario.SampleTime_s.']);

    end

end
